INSERT OR REPLACE INTO reviews (id, trip, name, email, rating, comment, lang, date, photos, reply_text, reply_date, created_at) VALUES ('24783f4e-6500-4486-840f-5f4cf782b1e8', 'zagora-erg-chegaga-3-day-excursion', 'Filippo Pratelli', NULL, 5, 'La nostra avventura nel deserto di Erg Chigaga è stata semplicemente fantastica! Dal momento della partenza fino al rientro, tutto è stato organizzato alla perfezione da Salah che ci ha accompagnato per piste sabbiose a scoprire un  viaggio berbero e a vedere la raccolta dei datteri. L’arrivo tra le dune al tramonto è stato magico — uno di quei momenti che restano per sempre nella memoria.

Il campo nel deserto era accogliente e curato, con tende sufficientemente confortevoli, cibo delizioso e un’atmosfera autentica. Dopo cena, abbiamo condiviso musica, tamburi e risate attorno al fuoco sotto un cielo stellato che toglieva il fiato. Bellissima anche se faticosa l''uscita in dromedario.

Un ringraziamento speciale dunque a Salah, gentilissimo sempre sorridente e cordiale, che ci ha fatto sentire a nostro agio come a casa facendoci scoprire la vera anima del Marocco.

Esperienza consigliatissima a chiunque voglia vivere la magia del Sahara, (rinunciando per un momento alle comodità della vita occidentale) in modo autentico e sicuro. Non vediamo l’ora di tornare, Inshallah!! ✨🐪', 'it', '2025-11-07', '[]', NULL, NULL, '2025-11-07T12:00:00.000Z');
INSERT OR REPLACE INTO reviews (id, trip, name, email, rating, comment, lang, date, photos, reply_text, reply_date, created_at) VALUES ('e8c31dd1-ddab-4a84-8f9a-3a2b9ffbfe3d', '6-day-sahara-odyssey', 'RIVIERE', NULL, 5, 'Un immense merci à Salah pour avoir organisé et accompagné notre séjour ! C''était une expérience véritablement authentique, pleine de découvertes et de moments de partage simples mais profonds. Cette belle parenthèse est idéale pour tous ceux qui sont curieux, aiment explorer et recherchent l''authenticité. Je recommande vivement cette expérience à tous !', 'fr', '2025-10-26', '[]', 'Votre message me touche énormément ❤️
Partager ces instants simples et vrais avec vous a été une expérience inoubliable aussi pour moi.
Le désert garde toujours la trace des belles rencontres, et la vôtre en fait partie. 🌵🌞', '2025-10-26', '2025-10-26T12:00:00.000Z');
INSERT OR REPLACE INTO reviews (id, trip, name, email, rating, comment, lang, date, photos, reply_text, reply_date, created_at) VALUES ('3b3778aa-05a6-49bf-9833-ce7c9549ab3c', '2-day-desert-escape', 'Konstantin Trucksäß', NULL, 5, 'Salah ist ein absoluter Ehrenmann. Meine Freundin und ich haben auf der Tour von Zagora in die Wüste Chigaga in zwei Tagen so viel erlebt und gesehen wie man sich nur wünschen kann. Nach einem kurzen Besuch einer traditionellen Töpferei, konnten wir nach dem ersten Teil des Hinwegs, welcher durch durch die Steinwüste im Atlasgebirge führt, schon die ersten Dünnen erklimmen. Danach gab es ein traditionelles Mittagessen. Alles war super sauber und mit Mineralwasser gewaschen, weshalb wir trotz empfindlichen "Touri-Magen" alles ohne Probleme essen konnten. Danach zeigte er uns auf einer Safari die einheimischen Tiere der marrokanischen Wüste. Von dem kleinen Atlashörchen über einen wilden Strauß bis zu Gazellen! Den Strauß konnten wir sogar mit einem Brot füttern :) Salah erzählt gerne und beantwortet alle Fragen, aber er ist auch ruhig und entspannt bei der Autofahrt. Das Dromedarreiten gegen Abend nach Ankunft in der Chigaga Wüste war toll und abends gab es sogar noch ein gemeinsames Lagerfeuer wo wir im Camp spontan zusammen Musik gemacht haben. Da es recht warm war,  haben wir nachts statt im Zelt unter freiem Sternenhimmel geschlafen, eine einzigartige Erfahrung!

Mit Salah hat man einen freundlichen, lustigen und offenen Guide, bei dem wir uns auf der Tour immer gut aufgehoben gefühlt haben! Ich würde die Tour wirklich jedem weiterempfehlen, der Lust hat die Marrokanische Wüste zu erkunden.', 'de', '2025-10-03', '["https://ik.imagekit.io/loverofsahara/reviews/666.jpg?updatedAt=1761815605644","https://ik.imagekit.io/loverofsahara/reviews/444.jpg?updatedAt=1761815606485","https://ik.imagekit.io/loverofsahara/reviews/333.jpg?updatedAt=1761815606806","https://ik.imagekit.io/loverofsahara/reviews/777.jpg?updatedAt=1761815606769"]', 'Hello 👋🏻 konstatin ,
J’espère qui vous êtes bien 👍 
Merci infiniment pour ce magnifique avis 🙏. Je suis très heureux que vous ayez apprécié chaque moment de cette aventure vers Zagora et Chegaga, du désert de pierre jusqu’aux nuits sous les étoiles ✨. Partager ces instants avec vous, entre découvertes, nature et musique autour du feu, a été aussi un vrai plaisir pour moi. Votre satisfaction est ma plus grande récompense. Vous serez toujours les bienvenus au Maroc pour de nouvelles expériences et découvertes', '2025-10-21', '2025-10-03T12:00:00.000Z');
INSERT OR REPLACE INTO reviews (id, trip, name, email, rating, comment, lang, date, photos, reply_text, reply_date, created_at) VALUES ('478fd161-3b53-4194-b8dd-0bbc9d187144', '2-day-desert-escape', 'Jara Neunhoeffer', NULL, 5, 'Salah hat uns sehr herzlich empfangen, man konnte wirklich spüren wie sehr er die Wüste liebt und er hat einen richtig mitgerissen.
Wir wurden direkt an der Busstation abgeholt und sind dann losgefahren, erst durch das Draatal in Richtung Sahara und dann gab es an der Dune de juif etwas Mittag zu essen, eine sehr liebevoll zubereitete Mahlzeit im Schatten eines Berberzeltes, alle Zutaten wurden dabei sogar mit Trinkwasser extra für uns gewaschen. 
Alles war perfekt geplant und vorbereitet, Dromedarwanderung, Mittag- und Abendessen, Angucken des Sonnenuntergangs, ohne dass man sich zu verplant gefühlt hat.
Es war sogar möglich direkt unter freiem Himmel zu schlafen und so den Sternenhimmel beobachten zu können.
Salah war ein super Guide und hat uns jederzeit willkommen fühlen lassen, kannte die Wüste wirklich perfekt, konnte jede unserer unzähligen Fragen beantworten und hat auch von sich aus erzählt.
Dadurch, dass Salah arabisch gesprochen hat, hat auch das die Kommunikation und das allgemeine Verständnis total erleichtert. Er kannte selbst die Besitzer unseres Riads in welchem wir im Anschluss waren und hat unseren Check in kurzerhand geregelt. Auch im Camp in der Wüste waren alle sehr freundlich und zuvorkommend und konnten Englisch und Französisch', 'de', '2025-10-03', '["https://ik.imagekit.io/loverofsahara/reviews/222.jpg?updatedAt=1761815606887","https://ik.imagekit.io/loverofsahara/reviews/111.jpg?updatedAt=1761815605840","https://ik.imagekit.io/loverofsahara/reviews/555.jpg?updatedAt=1761815606807"]', 'Hello 👋🏻 Jara ,
J’espère qui vous êtes bien 👍 
Merci infiniment pour ce magnifique avis 🙏. Je suis très heureux que vous ayez apprécié chaque moment de cette aventure vers Zagora et Chegaga, du désert de pierre jusqu’aux nuits sous les étoiles ✨. Partager ces instants avec vous, entre découvertes, nature et musique autour du feu, a été aussi un vrai plaisir pour moi. Votre satisfaction est ma plus grande récompense. Vous serez toujours les bienvenus au Maroc pour de nouvelles expériences et découvertes', '2025-10-21', '2025-10-03T12:00:00.000Z');
